SELECT id, tenant_id, conversation_id, turn_id, dispatch_attempt, event_seq, chunk_index,
       chunk_count, event_type, gmt_create,
       SUBSTRING(payload_fragment, 1, #{maxChars}) AS payload_fragment
FROM agent_conversation_turn_event
WHERE tenant_id = #{tenantId}
  AND turn_id = #{turnId}
  AND dispatch_attempt = #{dispatchAttempt}
  AND event_seq = #{eventSeq}
  AND chunk_index > #{afterChunkIndex}
ORDER BY chunk_index ASC
LIMIT #{limit}
